* AC and DC Input Source at non-inverting terminal vp (Fig 24.9)
Vinp vp 0 dc 0.9 ac 1

.control
  * 1. Operating point analysis for power dissipation
  op
  let pwr = -i(VDD) * 1.8
  print pwr
  let i_sink = @m.xm8b.msky130_fd_pr__nfet_01v8[id]
  print i_sink

  * 2. AC analysis for Gain, Bandwidth, PM, and GM (Fig 24.9, 24.10, 24.13)
  ac dec 100 1 1G
  let gain_db = vdb(vout)
  let phase = 180/PI * cph(v(vout))

  * Measure DC gain at 1 Hz
  meas ac aol_dc find gain_db at=1
  * Measure 3dB cutoff frequency (dominant pole)
  let aol_3db = aol_dc - 3.0
  meas ac f_3db when gain_db=aol_3db fall=1
  * Measure unity gain frequency (fun)
  meas ac f_un when gain_db=0 fall=1
  * Measure phase at fun and calculate Phase Margin (PM)
  meas ac phase_at_unity find phase when gain_db=0 fall=1
  let pm = 180 + phase_at_unity
  print pm
  * Measure Gain Margin (GM)
  meas ac gain_at_180 find gain_db when phase=-180 fall=1
  let gm = -gain_at_180
  print gm

  * 3. DC sweep for Output Voltage Swing and input-referred transfer curve
  dc Vinp 0.88 0.92 0.1m
  meas dc vout_max max v(vout)
  meas dc vout_min min v(vout)
  let v_swing = vout_max - vout_min
  print vout_max vout_min v_swing

  quit
.endc
.end

